+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("[^@\\s]+@[^@\\s]+\\.[^@\\s]+");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessageService service;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageService service) {
+        this.service = service;
+
+        // Eager so the server always has the typed value when Enter is pressed
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1), new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+
+        // Enter anywhere in the view sends; the Enter keydown is consumed, so Send's native click doesn't fire too
+        Shortcuts.addShortcutListener(this, this::sendMessage, Key.ENTER);
+        send.addClickListener(e -> sendMessage());
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(service.findAll());
+
+        configureLeaveDialog();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid, leaveDialog);
+    }
+
+    private void configureLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Span("The contact form has input that has not been sent. Leaving now discards it."));
+
+        Button keepEditing = new Button("Keep editing", e -> {
+            pendingNavigation = null;
+            leaveDialog.close();
+        });
+        Button discard = new Button("Discard", e -> {
+            leaveDialog.close();
+            if (pendingNavigation != null) {
+                var navigation = pendingNavigation;
+                pendingNavigation = null;
+                navigation.proceed();
+            }
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void sendMessage() {
+        if (!validate()) {
+            return;
+        }
+
+        service.add(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue()));
+        grid.setItems(service.findAll());
+        Notification.show("Message sent");
+
+        // Clearing the fields counts as an edit, so Send is switched off only after it
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        for (var field : new HasValidation[] { name, email, phone, message }) {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        }
+
+        if (name.getValue().isBlank()) {
+            invalidate(name, "Name is required");
+        }
+
+        var emailValue = email.getValue().trim();
+        var hasPhone = !phone.getValue().isBlank();
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            invalidate(email, "Enter a valid e-mail address");
+        } else if (emailValue.isEmpty() && !hasPhone) {
+            invalidate(email, "Give an e-mail address or a phone number");
+        }
+
+        if (message.getValue().isBlank()) {
+            invalidate(message, "Message is required");
+        } else if (message.getValue().length() > MAX_MESSAGE_LENGTH) {
+            invalidate(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+        }
+
+        return !name.isInvalid() && !email.isInvalid() && !message.isInvalid();
+    }
+
+    private static void invalidate(HasValidation field, String errorMessage) {
+        field.setInvalid(true);
+        field.setErrorMessage(errorMessage);
+    }
+}
