+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.BEFORE_EACH_TEST_METHOD)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @BeforeEach
+    void open() {
+        navigate(ContactView.class);
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return (Grid<ContactMessage>) $(Grid.class).single();
+    }
+
+    private void fillIn(String name, String email, String phone, String message) {
+        test(name()).setValue(name);
+        test(email()).setValue(email);
+        test(phone()).setValue(phone);
+        test(message()).setValue(message);
+    }
+
+    @Test
+    void headingAndAboutLinkArePresent() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("About", $(RouterLink.class).withText("About").single().getText());
+    }
+
+    @Test
+    void emptyFormIsEnabledAndShowsValidationErrors() {
+        assertTrue(send().isEnabled());
+
+        test(send()).click();
+
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(name().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertFalse($(Notification.class).exists());
+        assertEquals(0, grid().getGenericDataView().getItems().count());
+    }
+
+    @Test
+    void invalidEmailAndTooLongMessageAreReported() {
+        fillIn("Ann", "not-an-address", "", "x".repeat(501));
+
+        test(send()).click();
+
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertEquals("not-an-address", email().getValue());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void phoneOnlyIsEnoughAndSendingClearsTheFormAndDisablesSend() {
+        fillIn("Ann", "", "+358 40 123", "Hello there");
+
+        test(send()).click();
+
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+        ContactMessage first = grid().getGenericDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Ann", first.name());
+        assertEquals("Hello there", first.message());
+        assertEquals("", name().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+
+        test(name()).setValue("Bob");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        fillIn("Cat", "cat@example.com", "", "Via enter");
+
+        test(message()).setValue("Via enter");
+        fireShortcut(Key.ENTER);
+
+        assertTrue($(Notification.class).exists());
+        assertEquals("Via enter", grid().getGenericDataView().getItems().findFirst().orElseThrow().message());
+    }
+
+    @Test
+    void sentMessagesAreListedNewestFirstAndSurviveRevisiting() {
+        fillIn("First", "", "123", "one");
+        test(send()).click();
+        fillIn("Second", "", "456", "two");
+        test(send()).click();
+
+        navigate(ContactView.class);
+
+        assertEquals("Second", grid().getGenericDataView().getItems().findFirst().orElseThrow().name());
+        assertEquals(2, grid().getGenericDataView().getItems().count());
+    }
+
+    @Test
+    void leavingWithInputAsksFirstAndKeepEditingStaysOnView() {
+        test(name()).setValue("Dan");
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertEquals("Dan", name().getValue());
+
+        test(test(dialog).findInFooter(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(dialog.isOpened());
+        assertEquals("Dan", name().getValue());
+        assertTrue($(H1.class).withText("Contact").exists());
+    }
+
+    @Test
+    void discardingLeavesForTheAboutView() {
+        test(message()).setValue("Half written");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+
+        test(test(dialog).findInFooter(Button.class).withText("Discard").single()).click();
+
+        assertTrue($(H1.class).withText("About").exists());
+    }
+
+    @Test
+    void noDialogWhenAllFieldsAreEmpty() {
+        navigate(AboutView.class);
+
+        assertFalse($(Dialog.class).exists());
+        assertTrue($(H1.class).withText("About").exists());
+    }
+}
